func AggregateModels(records []logread.Record) ([]ModelTotals, Totals) {
	var all Totals
	var rows []ModelTotals
	index := make(map[modelKey]int)
	for _, rec := range records {
		all.Add(rec)
		key := modelKey{provider: rec.Provider, model: rec.Model}
		i, ok := index[key]
		if !ok {
